package com.aether.evaluation.service.impl;
import com.aether.evaluation.entity.*; import com.aether.evaluation.service.*; import com.baomidou.mybatisplus.core.toolkit.Wrappers; import org.springframework.stereotype.Service; import java.util.*; import java.math.BigDecimal; import com.alibaba.fastjson2.JSONObject;
@Service public class EvaluationGateServiceImpl implements EvaluationGateService {
 private final EvaluationPolicyService policyService; private final EvaluationExperimentService experimentService;
 public EvaluationGateServiceImpl(EvaluationPolicyService policyService, EvaluationExperimentService experimentService){this.policyService=policyService;this.experimentService=experimentService;}
 public Map<String,Object> check(String type,String id,String fingerprint){Map<String,Object> out=new LinkedHashMap<>();EvaluationPolicy p=policyService.getOne(Wrappers.lambdaQuery(EvaluationPolicy.class).eq(EvaluationPolicy::getTargetType,type).eq(EvaluationPolicy::getTargetId,id).eq(EvaluationPolicy::getDeleted,false),false);if(p==null||!Boolean.TRUE.equals(p.getRequired())){out.put("allowed",true);out.put("reasonCode","DISABLED");return out;}if(p.getDatasetVersionId()==null){out.put("allowed",false);out.put("reasonCode","NEEDS_CONFIGURATION");return out;}List<EvaluationExperiment> rows=experimentService.lambdaQuery().eq(EvaluationExperiment::getTargetType,type).eq(EvaluationExperiment::getTargetId,id).eq(EvaluationExperiment::getDatasetVersionId,p.getDatasetVersionId()).eq(EvaluationExperiment::getTargetFingerprint,fingerprint).eq(EvaluationExperiment::getScope,"FULL").eq(EvaluationExperiment::getStatus,"COMPLETED").orderByDesc(EvaluationExperiment::getFinishedAt).list();EvaluationExperiment e=rows.stream().filter(item->matchesPolicy(item,p)).findFirst().orElse(null);if(e==null){out.put("allowed",false);out.put("reasonCode","GATE_NOT_EVALUATED");return out;}boolean allowed="PASSED".equals(e.getQualityStatus());out.put("allowed",allowed);out.put("reasonCode",allowed?"PASSED":"GATE_FAILED");out.put("experimentId",e.getId());out.put("reportRevision",e.getReportRevision());return out;}
 private boolean matchesPolicy(EvaluationExperiment experiment,EvaluationPolicy policy){try{JSONObject c=JSONObject.parseObject(experiment.getConfigJson());if(c==null)return false;return same(c.getInteger("repeats"),policy.getRepeats(),1)&&same(c.getInteger("caseTimeoutSeconds"),policy.getCaseTimeoutSeconds(),300)&&same(c.getInteger("parallelism"),policy.getParallelism(),2)&&same(c.getBigDecimal("minimumScore"),policy.getMinimumScore()==null?BigDecimal.valueOf(80):BigDecimal.valueOf(policy.getMinimumScore()),BigDecimal.valueOf(80))&&same(c.getBigDecimal("minimumPassRate"),policy.getMinimumPassRate(),BigDecimal.valueOf(100));}catch(RuntimeException ex){return false;}}
 private boolean same(Integer actual,Integer expected,Integer fallback){return Objects.equals(actual,expected==null?fallback:expected);}
 private boolean same(BigDecimal actual,BigDecimal expected,BigDecimal fallback){return (actual==null?fallback:actual).compareTo(expected==null?fallback:expected)==0;}
}
